import * as Y from 'yjs';

const hex =
  '';

function hexToBytes(hex: string): Uint8Array {
  const bytes = new Uint8Array(hex.length / 2);
  for (let i = 0; i < hex.length; i += 2) {
    bytes[i / 2] = parseInt(hex.slice(i, i + 2), 16);
  }
  return bytes;
}

function renderXmlNode(node: Y.XmlElement | Y.XmlFragment | Y.XmlText, indent = 0): string {
  const pad = '  '.repeat(indent);

  if (node instanceof Y.XmlText) {
    const delta = node.toDelta();
    const parts = delta.map((op: any) => {
      if (op.attributes) {
        return `[${op.insert}](${JSON.stringify(op.attributes)})`;
      }
      return op.insert ?? '';
    });
    return `${pad}"${parts.join('')}"`;
  }

  const lines: string[] = [];
  const tag = node instanceof Y.XmlElement ? node.nodeName : '#fragment';
  const attrs =
    node instanceof Y.XmlElement
      ? Object.entries(node.getAttributes())
          .map(([k, v]) => ` ${k}="${v}"`)
          .join('')
      : '';

  lines.push(`${pad}<${tag}${attrs}>`);
  node.forEach((child) => {
    lines.push(renderXmlNode(child as any, indent + 1));
  });
  lines.push(`${pad}</${tag}>`);
  return lines.join('\n');
}

const doc = new Y.Doc();
Y.applyUpdate(doc, hexToBytes(hex));

// Access all known shared types to force correct type registration
const title = doc.getXmlFragment('title');
const docTitle = doc.getText('doc-title');
const blocks = doc.getMap('blocks');
const layout = doc.getArray('layout');
const metadata = doc.getMap('metadata');

console.log('=== Y.Doc Render ===\n');

console.log('--- doc-title (Y.Text / TipTap title editor) ---');
console.log('  plain text:', JSON.stringify(docTitle.toString()));
console.log('  delta:', JSON.stringify(docTitle.toDelta(), null, 2));
console.log();

console.log('--- title (Y.XmlFragment / ProseMirror) ---');
console.log(renderXmlNode(title));
console.log();

console.log('--- metadata (Y.Map) ---');
metadata.forEach((value: unknown, key: string) => {
  console.log(`  ${key}:`, JSON.stringify(value));
});
console.log();

console.log('--- layout (Y.Array, length=' + layout.length + ') ---');
const layoutArr = layout.toArray();
layoutArr.forEach((group: any, i: number) => {
  if (group && typeof group.toJSON === 'function') {
    console.log(`  [${i}]:`, JSON.stringify(group.toJSON(), null, 2));
  } else {
    console.log(`  [${i}]:`, JSON.stringify(group, null, 2));
  }
});
console.log();

console.log('--- blocks (Y.Map, size=' + blocks.size + ') ---');
blocks.forEach((block: unknown, id: string) => {
  if (block instanceof Y.XmlElement) {
    const attrs = block.getAttributes();
    console.log(`  [${id}] <${block.nodeName}>`, JSON.stringify(attrs));
    block.forEach((child) => {
      if (child instanceof Y.XmlText) {
        const text = child.toString();
        if (text) console.log(`    text: ${JSON.stringify(text)}`);
      } else if (child instanceof Y.XmlElement) {
        console.log(`    <${child.nodeName}>`, JSON.stringify(child.getAttributes()));
      }
    });
  } else {
    console.log(`  [${id}]:`, JSON.stringify(block));
  }
});
